from lib import *
S = SS('n26')
steps = [
    step("同一个结构体 N int,四个 tag 写成不同名字(json:\"j_n\" form:\"f_n\" uri:\"u_n\" header:\"X-H-N\")。请求 /q/3?f_n=1&j_n=9&u_n=8&n=7&N=6 并带头 X-H-N: 5:ShouldBindQuery 取到 1(读 form 标签,不是 query),ShouldBindUri 取到 3(读 uri 标签),ShouldBindHeader 取到 5(读 header 标签),ShouldBindJSON 取到 11(读 json 标签),表单 ShouldBind 取到 21。JSON 键不区分大小写(\"J_N\":15 也能绑上),表单键区分大小写(F_N=24 绑不上,得 0)。", t=tl(S(1)), mark=lidx(S(1), 'ShouldBindQuery → {"j_n":1}', 'ShouldBindJSON → {"j_n":11}', 'ShouldBind(表单) → {"j_n":21}'), done=lidx(S(1), 'JSON 键不区分大小写', '表单键区分大小写'), b=bars([['ShouldBindQuery(form 标签)', 1, '1'], ['ShouldBindUri(uri 标签)', 3, '3'], ['ShouldBindHeader(header 标签)', 5, '5'], ['ShouldBindJSON(json 标签)', 11, '11'], ['ShouldBind 表单(form 标签)', 21, '21']], 21, done=[0, 1, 2, 3, 4]), kv=KV([['Query', '用 form 标签(没有 query 标签)'], ['JSON 键', '不区分大小写'], ['表单键', '区分大小写']], ['Query'])),
    step("没有 tag 时 key 就是字段名本身,且区分大小写:?Name=Ann 能绑到 Name,?name=Ann 和 ?NAME=Ann 都绑不上;form:\"-\" 的 Secret 与未导出的 hidden 永远不会被绑定;Age 写了 form:\"age\",所以 ?Age=40 无效、?age=41 才有效;Page 没传时取 default=1。", t=tl(S(2)), mark=lidx(S(2), '/x?name=Ann&age=30', '/x?NAME=Ann', '/x?Secret=s&hidden=h&age=1', '/x?Age=40&age=41'), done=lidx(S(2), '/x?Name=Ann&age=30'), kv=KV([['无 tag', 'key = 字段名,区分大小写'], ['form:"-"', '忽略该字段'], ['未导出字段', '忽略']], ['无 tag'])),
    step("ShouldBind 选哪个绑定器只看方法和 Content-Type(binding.Default):GET 永远是 form,不管 Content-Type;POST/PUT/DELETE 按类型选 json、xml、yaml、toml、protobuf、multipart,application/x-www-form-urlencoded 与 text/plain 与没有 Content-Type 都是 form。", t=tl(S(3)), mark=lidx(S(3), '"application/json"', '""   '), done=lidx(S(3), 'Content-Type'), kv=KV([['GET', '永远 form'], ['POST + json', 'json'], ['未知 / 缺失的类型', '退回 form']], ['GET'])),
    step("后果:GET 带 JSON body 的请求,ShouldBind 用的是 form,body 被忽略,绑出 {n:0},没有任何错误;POST 带 JSON body 但没有 Content-Type 也走 form,得到 0;Content-Type 写成 application/json; charset=utf-8 仍是 json(c.ContentType() 会去掉参数);POST 表单 n=6 加 URL 里的 ?n=7:表单绑定取 6;POST JSON 加 ?n=8:JSON 绑定取 9,URL 里的被忽略。", t=tl(S(4)), mark=lidx(S(4), 'GET  + JSON body', 'POST + JSON body 但没有 Content-Type'), done=lidx(S(4), 'charset=utf-8', 'POST + 表单 n=6', 'POST + JSON body 且 URL'), kv=KV([['GET + JSON body', '被忽略,n=0,err=nil'], ['缺 Content-Type', '走 form,JSON body 被忽略'], ['charset 参数', '不影响选择']], ['GET + JSON body'])),
    step("嵌入结构体(Base)的字段直接展开(?id=1);匿名内嵌的普通结构体字段(Inner.X)用 ?x=2;指针结构体 Opt 只有请求里出现了它的字段才分配(只传 id 时 Opt 是 nil,传 level 才非 nil);指针字段 P 同理。写了 form 标签的结构体字段 Sub 不是展开,而是把参数值当 JSON 解码:?sub={\"Level\":5} 能用,?sub=5 报 json: cannot unmarshal number …;没有对应参数时 Sub 仍会像普通嵌套那样被展开(?level=3 同时填了 Opt.Level 与 Sub.Level)。", t=tl(S(5)), mark=lidx(S(5), '/x?sub=5', '/x?level=3'), done=lidx(S(5), '/x?id=1&x=2', '/x?id=1  '), kv=KV([['嵌入 / 匿名结构体', '字段展开,不需要前缀'], ['指针结构体', '请求里有它的字段才分配'], ['带 form 标签的结构体', '参数值按 JSON 解码']], ['带 form 标签的结构体'])),
]
A = mkartn('n26', 26, 'Gin,参数绑定,binding tag,form,json,uri,header,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测绑定 tag:ShouldBindQuery 读的是 form 标签而不是 query;uri、header、json 各读各的;没有 tag 时 key 是区分大小写的字段名;ShouldBind 对 GET 永远用 form,带 JSON body 的 GET 被忽略且没有错误;带 form 标签的结构体字段按 JSON 解码。',
    'form、json、uri、header、query 这些 tag 到底谁读谁?没写 tag 时用什么名字?ShouldBind 是怎么决定该用哪个绑定器的?这篇用同一个结构体、四个不同的 tag 名,把每种来源读到的值一个个对出来,再看几个容易踩的边界。',
    [('1 / 3 / 5 / 11', 'ShouldBindQuery / Uri / Header / JSON 对同一结构体分别读到的值(四个 tag 名不同)'), ('区分大小写', '没有 tag 时 key=字段名:?Name 能绑,?name 不能'), ('GET 忽略 body', 'GET + JSON body 经 ShouldBind 绑出 0,没有错误')],
    [('各读各的 tag', '<p><code>ShouldBindJSON</code> 读 <code>json</code> 标签,<code>ShouldBindUri</code> 读 <code>uri</code>,<code>ShouldBindHeader</code> 读 <code>header</code>,而 <code>ShouldBindQuery</code> 和表单绑定读的都是 <code>form</code>——Gin 没有 <code>query</code> 标签。同一个结构体想同时支持几种来源,就把几个 tag 都写上。JSON 键由 <code>encoding/json</code> 匹配,不区分大小写;表单和查询串的键区分大小写。</p>'),
     ('没有 tag 的字段', '<p>不写 tag 时 key 取字段名本身(<code>Name</code> 就是 <code>Name</code>,不会转小写),所以 <code>?name=</code> 绑不上 <code>Name</code>。<code>form:"-"</code> 与未导出字段不参与绑定。<code>form:"page,default=1"</code> 这样的选项可以给缺省值。</p>'),
     ('ShouldBind 怎么选', '<p><code>binding.Default(method, contentType)</code> 是个纯函数:GET 总是 form;其它方法按 Content-Type 选,不认识的类型和缺失的类型都退回 form。注意比较的是去掉参数之后的类型(<code>application/json; charset=utf-8</code> 仍是 json)。</p>'),
     ('两个容易踩的坑', '<p>第一,GET 请求带 JSON body 时,<code>ShouldBind</code> 默默地用 form 绑定,body 被忽略,而且没有任何错误——字段全是零值。第二,POST 的 JSON 请求忘了设 Content-Type,同样退回 form。想要明确的行为就直接调用 <code>ShouldBindJSON</code> 之类的专用方法。</p>'),
     ('嵌套与指针', '<p>嵌入的、匿名的结构体字段直接展开;指针结构体只有请求里出现了它的字段才会被分配,所以 <code>nil</code> 可以表示“没传”。给结构体字段写了 <code>form</code> 标签时,Gin 把参数值整个当 JSON 解码到这个结构体里,而不是展开它的字段。</p>')],
    steps,
    [ENV_N_GIN + '。请求用 httptest 直接调用 ServeHTTP;表格那一节直接调用 binding.Default 这个纯函数;每种情形各一次',
     '没有验证:multipart 表单与文件字段的 tag(后面上传的文章会涉及);XML、YAML、TOML 的 tag 与大小写规则;自定义类型实现 BindUnmarshaler 的行为(源码里有,没有跑);parser=encoding.TextUnmarshaler 选项;header 标签里带下划线的头名的规范化'],
    '绑定 tag')
